/* Copia de respaldo de las fotos: se usa solo si la carpeta img/ no se encuentra. */
window.FOTOS={"chorizos.jpg": "data:image/jpeg;base64,", "costillas.jpg": "data:image/jpeg;base64,", "papas.jpg": "data:image/jpeg;base64,", "parrillada.jpg": "data:image/jpeg;base64,", "titanic.jpg": "data:image/jpeg;base64,"};
function imgFallback(i){var k=(i.getAttribute('src')||'').split('/').pop();
if(window.FOTOS&&FOTOS[k]&&i.src!==FOTOS[k]){i.onerror=function(){i.style.visibility='hidden'};i.src=FOTOS[k]}else if(i.id==='mImg'){i.style.visibility='hidden'}else{i.remove()}}
